common:
/* Pretendard v1.3.9 Medium: one static face. See assets/Pretendard-OFL.txt. */


:host {
  color-scheme: light;
  --surface: #fff;
  --ink: #162039;
  --muted: #4d5a74;
  --accent: #4338ca;
  --line: #dce2ef;
  --tint: #f0efff;
  --brown: #392A20;
  --navy: #2B2C43;
  --cream: #FAF7E9;
  --text-light: #F2E4C9;
  --highlight: #FFE98A;
  --highlight-ink: #3D3326;
  --font-family: 'TeamPretendard', system-ui, -apple-system, 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
  font-family: var(--font-family);
}

.highlight {
  display: inline;
  background: var(--highlight);
  color: var(--highlight-ink);
  padding-block: 0;
  padding-inline: 4px;
  margin-inline: -4px; /* Extend the paint without shifting the text. */
  border-radius: 0;
  box-shadow: none;
}

.bg-brown { background-color: var(--brown); }

*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; background: var(--surface); color: var(--ink); }
html { overscroll-behavior-x: none; }

.stage {
  touch-action: pan-y pinch-zoom;
}

.stage:empty, .slide, .deck-message {
  min-block-size: 1080.0000px;
  min-block-size: 1080.0000px;
}

.slide {
  --gutter: clamp(1.25rem, 115.2000px, 5rem);
  --inset: clamp(1.5rem, 64.8000px, 5rem);
  display: grid;
  grid-template-columns: minmax(0, 68rem);
  justify-content: center;
  align-content: center;
  gap: clamp(.9rem, 53.7600px, 2rem);
  padding: var(--inset) var(--gutter);
  padding: calc(var(--inset) + env(safe-area-inset-top))
           calc(var(--gutter) + env(safe-area-inset-right))
           calc(var(--inset) + env(safe-area-inset-bottom))
           calc(var(--gutter) + env(safe-area-inset-left));
  word-break: keep-all;
  overflow-wrap: anywhere;
}

.slide h1, .slide h2, .slide p { margin: 0; }
.slide h1 { font-size: clamp(2rem, 115.2000px, 5.25rem); line-height: 1.12; letter-spacing: -.045em; }
.slide .eyebrow { color: var(--accent); font-size: clamp(.875rem, 28.8000px, 1.05rem); font-weight: 780; letter-spacing: .08em; }
.slide .lead { max-width: 44ch; color: var(--muted); font-size: clamp(1.05rem, 51.8400px, 1.6rem); line-height: 1.6; }

.slide--cover {
  background: radial-gradient(ellipse at top right, #dbddff, transparent 70%), var(--surface);
}

.slide--cover .chip {
  justify-self: start;
  border: 1px solid #d8d5ff;
  border-radius: 1920.0000px;
  padding: .425rem .8rem;
  background: var(--tint);
  color: var(--accent);
  font-size: clamp(.875rem, 28.8000px, 1rem);
  font-weight: 700;
}

.two-column { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: clamp(.75rem, 48.0000px, 1.5rem); }
.card {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: .6rem;
  border: 1px solid var(--line);
  border-radius: 1rem;
  padding: clamp(1rem, 57.6000px, 1.75rem);
  background: #f8f9fd;
}
.card h2 { font-size: clamp(1.125rem, 46.0800px, 1.6rem); }
.card p { color: var(--muted); font-size: clamp(1rem, 32.6400px, 1.2rem); line-height: 1.65; }
.slide img { display: block; max-width: 100%; height: auto; }

.deck-message { margin: 0; padding: 1.5rem; display: grid; place-items: center; color: var(--muted); text-align: center; }
@media (scripting: none) { .stage:empty { display: none; } }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (max-width: 42rem) {
  .two-column { grid-template-columns: minmax(0, 1fr); }
}

