    /* Title slide background. */
    .stage:has(> .title-slide) {
      position: fixed;
      inset: 0;
      overflow: hidden;
      background: var(--brown);
    }

    .stage > .title-slide {
      position: absolute;
      top: 50%;
      left: 50%;
      width: min(1920.0000px, calc(1080.0000px * 16 / 9));
      aspect-ratio: 1920 / 1080;
      min-block-size: 0;
      padding: 0;
      transform: translate(-50%, -50%);
    }

    @supports (transform: scale(tan(atan2(1px, 1px)))) {
      .stage > .title-slide {
        width: 1920px;
        height: 1080px;
        transform: translate(-50%, -50%)
          scale(min(tan(atan2(1920.0000px, 1920px)), tan(atan2(1080.0000px, 1080px))));
      }
    }

    .stage > .title-slide > .phone-frames {
      position: absolute;
      left: 49.6875%; /* Reference x = 636 of 1280. */
      top: 10.2777777778%; /* Reference y = 74, with 16:9 stage height extended to 720. */
      width: 44.84375%; /* Reference crop width = 574 of 1280. */
      height: auto;
      display: block;
      pointer-events: none;
    }

    /* On taller landscape screens, keep the 16:9 cover flush with the bottom. */
    @media screen and (orientation: landscape) and (aspect-ratio < 16/9) {
      .stage > .title-slide {
        top: auto;
        bottom: 0;
        transform: translateX(-50%);
        transform-origin: center bottom;
      }

      @supports (transform: scale(tan(atan2(1px, 1px)))) {
        .stage > .title-slide {
          transform: translateX(-50%) scale(tan(atan2(1920.0000px, 1920px)));
        }
      }
    }

    @media print {
      .stage > .title-slide {
        position: static;
        width: 1920px;
        height: 1080px;
        background: var(--brown);
        transform: none;
        print-color-adjust: exact;
      }
    }

