interview.css:
.slide.brown-blank { position: fixed; inset: 0; background-color: var(--navy); }
.brown-blank > .slide-folio { display: none; }
.interview-wave {
  position: absolute;
  --wave-top: calc(max(97.2000px, 2rem) + env(safe-area-inset-top));
  --wave-height: clamp(5rem, 162.0000px, 8rem);
  --wave-end: calc(var(--wave-top) + var(--wave-height));
  --caption-lead: clamp(.75rem, 32.4000px, 1.5rem);
  --reference-gap: clamp(.25rem, 9.7200px, .65rem);
  --caption-space: calc(1080.0000px - 2 * var(--wave-end) - var(--caption-lead));
  /* Keep the original type scale; distribute the remaining space over three gaps. */
  --fit-height: calc((var(--caption-space) - 4 * var(--reference-gap)) / 5.4);
  --caption-size: max(.75rem, min(94.0800px, var(--fit-height)));
  --caption-gap: clamp(var(--reference-gap), calc((var(--caption-space) - 4.32 * var(--caption-size)) / 3), 54.0000px);
  inset-block-start: var(--wave-top);
  inset-inline: 0;
  display: grid;
  justify-items: center;
  gap: var(--caption-lead);
  color: var(--text-light);
  text-align: center;
}
.interview-wave__signal {
  display: block;
  inline-size: min(30rem, calc(100% - 3rem));
  block-size: var(--wave-height);
}
.interview-wave__captions {
  display: grid;
  gap: var(--caption-gap);
  padding-inline: clamp(.5rem, 57.6000px, 3rem);
  color: var(--text-light);
  font: 500 calc(var(--caption-size) * 0.7)/1.08 var(--font-family);
  letter-spacing: -.025em;
  white-space: nowrap;
}

