limits.css:
/* Fixed 16:9 canvas, scoped to this slide while it is mounted. */
.stage:has(> .s04-limitations) {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: var(--brown);
}
.stage > .s04-limitations {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(1920.0000px, calc(1080.0000px * 16 / 9));
  aspect-ratio: 1920 / 1080;
  min-block-size: 0;
  container-type: inline-size;
  display: block;
  overflow: hidden;
  padding: 0;
  background: var(--brown);
  color: var(--brown);
  transform: translate(-50%, -50%);
}
@supports (transform: scale(tan(atan2(1px, 1px)))) {
  .stage > .s04-limitations {
    width: 1920px;
    height: 1080px;
    transform: translate(-50%, -50%)
      scale(min(tan(atan2(1920.0000px, 1920px)), tan(atan2(1080.0000px, 1080px))));
  }
}

/* Fixed-size layers share an arrival point. A fresh clone from deck.js
   resets the CSS timeline on every entry. */
.s04-limitations .s04-thread {
  --s04-line: 3.7916667cqw;
  --s04-padding-block: 1.40625cqw;
  --s04-row-gap: 1.25cqw;
  --s04-bubble-height: calc(2 * var(--s04-line) + 2 * var(--s04-padding-block));
  --s04-step: calc(var(--s04-bubble-height) + var(--s04-row-gap));
  --s04-duration: .386666666666667s;
  --s04-easing: cubic-bezier(.22, .61, .36, 1);
  --s04-first: .133333333333333s;
  --s04-second: calc(var(--s04-first) + 1s);
  --s04-third: calc(var(--s04-second) + 1s);
  --s04-focus-delay: calc(var(--s04-third) + var(--s04-duration) + 1.5s);
  --s04-focus-duration: .35s;
  --s04-focus-blur: .080729166666667cqw; /* 1.55 px at 1920 px */
  --s04-ink: #585653;
  position: absolute;
  inset-inline: 18.75cqw;
  inset-block-end: calc(50% - (3 * var(--s04-bubble-height) + 2 * var(--s04-row-gap)) / 2);
  list-style: none;
  margin: 0;
  padding: 0;
  font: 500 2.708333cqw / var(--s04-line) var(--font-family);
  letter-spacing: -.025em;
}
.s04-limitations .s04-message {
  --s04-delay: var(--s04-first);
  --s04-rise: var(--s04-row-gap);
  position: absolute;
  inset-inline: 0;
  inset-block-end: 0;
  block-size: var(--s04-bubble-height);
  will-change: transform;
}
/* Incoming and earlier bubbles share the same easing. The incoming bubble
   starts half a gap below its predecessor and ends one full gap below it. */
.s04-limitations .s04-message:first-child {
  animation: s04-push-once var(--s04-duration) var(--s04-easing) var(--s04-second) forwards,
             s04-push-again var(--s04-duration) var(--s04-easing) var(--s04-third) forwards;
}
.s04-limitations .s04-message:nth-child(n+2) {
  --s04-rise: calc(var(--s04-bubble-height) + var(--s04-row-gap) / 2);
}
.s04-limitations .s04-message:nth-child(2) {
  --s04-delay: var(--s04-second);
  animation: s04-push-once var(--s04-duration) var(--s04-easing) var(--s04-third) forwards;
}
.s04-limitations .s04-message:nth-child(3) {
  --s04-delay: var(--s04-third);
}
.s04-limitations .s04-bubble {
  block-size: 100%;
  padding: var(--s04-padding-block) 2.291667cqw;
  border-radius: 1.875cqw 1.875cqw 1.875cqw .43cqw;
  background: #FFFFFF;
  color: var(--s04-ink);
  visibility: hidden;
  opacity: 0;
  will-change: transform, opacity;
  animation: s04-rise-in var(--s04-duration) var(--s04-easing) var(--s04-delay) both;
}
@property --s04-focus-stroke {
  syntax: '<length>';
  inherits: false;
  initial-value: 0px;
}
/* Only the text changes, once the last slide-in has settled. The mark
   shares the normal baseline throughout, so the two-line layout stays put. */
.s04-limitations .s04-bubble mark.highlight {
  color: inherit;
  background: transparent;
  line-height: 0;
  -webkit-text-stroke: var(--s04-focus-stroke, 0px) currentColor;
  animation: s04-focus-mark var(--s04-focus-duration) ease-out var(--s04-focus-delay) forwards;
}
.s04-limitations .s04-plain {
  animation: s04-focus-plain var(--s04-focus-duration) ease-out var(--s04-focus-delay) forwards;
}
@keyframes s04-focus-mark {
  from { color: var(--s04-ink); background-color: transparent; font-size: 1em; --s04-focus-stroke: 0px; }
  to { color: var(--highlight-ink); background-color: var(--highlight); font-size: calc(1em + .15625cqw); --s04-focus-stroke: 1.55px; }
}
@keyframes s04-focus-plain {
  from { color: var(--s04-ink); filter: none; }
  to { color: #757370; filter: blur(var(--s04-focus-blur)); }
}
.s04-limitations .s04-message:nth-child(3) .s04-bubble {
  white-space: nowrap; /* Keep the authored <br> as the only break. */
}
.s04-limitations .s04-message:nth-child(2) .s04-bubble {
  border-bottom-left-radius: 1.875cqw;
  border-bottom-right-radius: .43cqw;
}
@keyframes s04-push-once {
  from { transform: translateY(0); }
  to { transform: translateY(calc(-1 * var(--s04-step))); }
}
@keyframes s04-push-again {
  from { transform: translateY(calc(-1 * var(--s04-step))); }
  to { transform: translateY(calc(-2 * var(--s04-step))); }
}
@keyframes s04-rise-in {
  from { visibility: hidden; opacity: 0; transform: translateY(var(--s04-rise)); }
  to { visibility: visible; opacity: 1; transform: translateY(0); }
}

/* Retain the reading pauses, but make each update instantaneous. */
@media (prefers-reduced-motion: reduce) {
  .s04-limitations .s04-thread {
    --s04-first: 0s;
    --s04-duration: 0s;
    --s04-focus-duration: 0s;
  }
  .s04-limitations .s04-message,
  .s04-limitations .s04-bubble { will-change: auto; }
}
@media (forced-colors: active) {
  .s04-limitations .s04-thread { --s04-focus-blur: 0px; }
}

question.css:
/* Fixed 16:9 canvas, scoped to this slide while it is mounted. */
.stage:has(> .s05-limitations) {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: var(--brown);
}
.stage > .s05-limitations {
  position: absolute;
  inset: 0;
  min-block-size: 0;
  display: block;
  overflow: hidden;
  padding: 0;
  background: transparent;
  color: var(--brown);
}
.s05-limitations .s05-canvas {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(1920.0000px, calc(1080.0000px * 16 / 9));
  aspect-ratio: 1920 / 1080;
  container-type: inline-size;
  transform: translate(-50%, -50%);
  background: transparent;
}
.s05-limitations .s05-canvas--title { z-index: 2; pointer-events: none; }
@supports (transform: scale(tan(atan2(1px, 1px)))) {
  .s05-limitations .s05-canvas {
    width: 1920px;
    height: 1080px;
    transform: translate(-50%, -50%)
      scale(min(tan(atan2(1920.0000px, 1920px)), tan(atan2(1080.0000px, 1080px))));
  }
}

/* Reveal the veil first; use an opaque fallback when blur is unavailable. */
.stage > .s05-limitations::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background: #251A14;
  animation: s05-veil-fallback 650ms ease-in-out both;
}
@supports ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .stage > .s05-limitations::after {
    background: rgb(37 26 20 / 86%);
    -webkit-backdrop-filter: blur(calc(min(1920.0000px, 1080.0000px * 16 / 9) * .009375));
    backdrop-filter: blur(calc(min(1920.0000px, 1080.0000px * 16 / 9) * .009375));
    animation: s05-veil 650ms ease-in-out both;
  }
}
@keyframes s05-veil-fallback {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes s05-veil {
  from {
    background: rgb(37 26 20 / 0%);
    -webkit-backdrop-filter: blur(0);
    backdrop-filter: blur(0);
  }
  to {
    background: rgb(37 26 20 / 86%);
    -webkit-backdrop-filter: blur(calc(min(1920.0000px, 1080.0000px * 16 / 9) * .009375));
    backdrop-filter: blur(calc(min(1920.0000px, 1080.0000px * 16 / 9) * .009375));
  }
}
@keyframes s05-question-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

.s05-limitations .s05-question {
  position: absolute;
  inset: 0;
  z-index: 2147483647;
  display: grid;
  place-items: center;
  margin: 0;
  color: var(--text-light);
  font-size: 5.208333cqw;
  line-height: 1.12;
  letter-spacing: -.045em;
  white-space: nowrap;
  pointer-events: none;
  animation: s05-question-fade 350ms ease-in-out 650ms both;
}
@media (prefers-reduced-motion: reduce), print {
  .stage > .s05-limitations::after,
  .s05-limitations .s05-question { animation: none; }
}

/* Fixed-size layers remain at their final positions. */
.s05-limitations .s05-thread {
  --s05-line: 3.7916667cqw;
  --s05-padding-block: 1.40625cqw;
  --s05-row-gap: 1.25cqw;
  --s05-bubble-height: calc(2 * var(--s05-line) + 2 * var(--s05-padding-block));
  --s05-step: calc(var(--s05-bubble-height) + var(--s05-row-gap));
  position: absolute;
  inset-inline: 18.75cqw;
  inset-block-end: calc(50% - (3 * var(--s05-bubble-height) + 2 * var(--s05-row-gap)) / 2);
  list-style: none;
  margin: 0;
  padding: 0;
  font: 500 2.708333cqw / var(--s05-line) var(--font-family);
  letter-spacing: -.025em;
}
.s05-limitations .s05-message {
  position: absolute;
  inset-inline: 0;
  inset-block-end: 0;
  block-size: var(--s05-bubble-height);
}
.s05-limitations .s05-message:first-child {
  transform: translateY(calc(-2 * var(--s05-step)));
}
.s05-limitations .s05-message:nth-child(2) {
  transform: translateY(calc(-1 * var(--s05-step)));
}
.s05-limitations .s05-bubble {
  block-size: 100%;
  padding: var(--s05-padding-block) 2.291667cqw;
  border-radius: 1.875cqw 1.875cqw 1.875cqw .43cqw;
  background: #FFFFFF;
  color: #585653;
  visibility: visible;
  opacity: 1;
  transform: translateY(0);
}
.s05-limitations .s05-bubble mark.highlight {
  font-size: calc(1em + 0.15625cqw); /* +3 px on the 1920 px design stage */
  line-height: 0; /* Keep the surrounding text on its original baselines. */
  -webkit-text-stroke: 1.55px currentColor;
}
.s05-limitations .s05-message:nth-child(3) .s05-bubble {
  white-space: nowrap; /* Keep the authored <br> as the only break. */
}
.s05-limitations .s05-message:nth-child(2) .s05-bubble {
  border-bottom-left-radius: 1.875cqw;
  border-bottom-right-radius: .43cqw;
}

feedback.css:
.stage:has(> .s08-feedback){position:fixed;inset:0;background:var(--brown);display:grid;place-items:center}
.stage>.s08-feedback{width:min(1920.0000px,1920.0000px);aspect-ratio:16/9;min-block-size:0;padding:0;gap:0;display:grid;place-items:center;grid-template-columns:1fr;container-type:inline-size;color:var(--text-light)}
.s08-feedback .s08-flow{width:94cqw}
.s08-feedback .s08-label{margin:0 0 2cqw;color:var(--highlight);font:700 3cqw/1.2 var(--font-family);letter-spacing:-.045em}
.s08-feedback .s08-quotes{list-style:none;margin:0;padding:0;display:grid;gap:1.4cqw}
.s08-feedback .s08-quote{margin:0;padding:2.1cqw 2.2cqw;display:flex;align-items:baseline;gap:1.8cqw;background:var(--text-light);color:var(--highlight-ink);border-left:.5cqw solid #B99F85}
.s08-feedback .s08-quote b{flex:none;font:700 1.8cqw/1.2 var(--font-family);color:#846D5C;letter-spacing:-.02em;white-space:nowrap}
.s08-feedback .s08-quote p{margin:0;min-width:0;font:500 2.18cqw/1.5 var(--font-family);letter-spacing:-.035em;white-space:nowrap}
.s08-feedback .s08-reply{visibility:hidden;background:transparent;color:var(--text-light);border-left-color:var(--text-light);box-shadow:inset 0 0 0 .2cqw var(--text-light)}
.s08-feedback .s08-reply b{color:var(--highlight);font-size:2.6cqw;line-height:1;min-width:4.3cqw}
.s08-feedback[data-step="1"] .s08-reply--1,.s08-feedback[data-step="2"] .s08-reply--1,.s08-feedback[data-step="2"] .s08-reply--2{visibility:visible}
@media screen and (prefers-reduced-motion: no-preference) {
  .s08-feedback .s08-flow{animation:s08-enter 340ms ease-out 180ms both}
  .stage[aria-busy="true"]>.s08-feedback .s08-flow{animation-play-state:paused}
  .s08-feedback[data-step="1"] .s08-reply--1,.s08-feedback[data-step="2"] .s08-reply--1,.s08-feedback[data-step="2"] .s08-reply--2{animation:s08-enter 300ms ease-out both}
  @keyframes s08-enter{from{opacity:0;transform:translateY(.65cqw)}to{opacity:1;transform:translateY(0)}}
